export const PUBLICATION_CATEGORIES = CATEGORY_NAMES.map((name) => {
  const count = PUBLICATIONS.filter((post) => post.category === name).length;
  return { name, count, size: 112 + count * 13 };
});

export function getPublicationBySlug(slug: string) {
  return PUBLICATIONS.find((post) => post.slug === slug);
}

export function getNextPublication(slug: string) {
  const index = PUBLICATIONS.findIndex((post) => post.slug === slug);
  if (index < 0) return PUBLICATIONS[0];
  return PUBLICATIONS[(index + 1) % PUBLICATIONS.length];
}
